const uint N = rows * I;
const uint base = thread_position_in_grid.x * 16;
if (base >= N) return;
if (base + 16 <= N) {
    uint4 g0 = ld16(g + base), g1 = ld16(g + base + 8);
    uint4 u0 = ld16(u + base), u1 = ld16(u + base + 8);
    st16(out + base, swg8(g0, u0));
    st16(out + base + 8, swg8(g1, u1));
} else {
    for (uint i = base; i < min(base + 16, N); ++i) {
        float a = float(g[i]);
        float e = metal::fast::exp2(metal::min(-a * 1.4426950408889634f, 100.0f));
        out[i] = half(a * metal::fast::divide(1.0f, 1.0f + e) * float(u[i]));
    }
}

