inline uint4 ld16(const device half* p) { return *(const device uint4*)p; }
inline uint4 ld16(const constant half* p) { return *(const constant uint4*)p; }
inline void st16(device half* p, uint4 v) { *(device uint4*)p = v; }
inline float4 swg(float4 a, float4 b) {
    float4 e = metal::fast::exp2(metal::min(a * -1.4426950408889634f, float4(100.0f)));
    return (a * b) * metal::fast::divide(float4(1.0f), 1.0f + e);
}
inline uint4 swg8(uint4 ga, uint4 ua) {
    float4 a0 = float4(as_type<half4>(ga.xy)), a1 = float4(as_type<half4>(ga.zw));
    float4 b0 = float4(as_type<half4>(ua.xy)), b1 = float4(as_type<half4>(ua.zw));
    uint4 o;
    o.xy = as_type<uint2>(half4(swg(a0, b0)));
    o.zw = as_type<uint2>(half4(swg(a1, b1)));
    return o;
}
